import sys
data = list(map(int, sys.stdin.buffer.read().split()))
n = data[0]
a = data[1:1 + n]
ans = []
for i in range(n):
    found_later = False
    for j in range(i + 1, n):
        if a[i] == a[j]:
            found_later = True
            break
    appeared_earlier = False
    for k in range(i):
        if a[i] == a[k]:
            appeared_earlier = True
            break
    if found_later and not appeared_earlier:
        ans.append(str(a[i]))
print('\n'.join(ans) if ans else 'None')
